{{- if eq .Values.global.userPlaneArchitecture "single" }}
{{- with .Values.upf }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}
  labels:
    {{- include "free5gc-upf.labels" $ | nindent 4 }}
    project: {{ $.Values.global.projectName }}
    nf: {{ .name }}
spec:
  {{- if not .autoscaling.enabled }}
  replicas: {{ .replicaCount }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "free5gc-upf.selectorLabels" $ | nindent 6 }}
      project: {{ $.Values.global.projectName }}
      nf: {{ .name }}
  template:
    metadata:
      annotations:
        {{- include "free5gc-upf.upfAnnotations" $ | nindent 8 }}
        {{- if $.Values.global.upf.multus.enabled }}
        k8s.v1.cni.cncf.io/networks: '[
            { "name": "{{ $.Values.global.upf.multus.n3network.name }}-{{ include "free5gc-upf.fullname" $ }}",
              "interface": "n3",
              "ips": [ "{{ $.Values.global.upf.multus.upf.n3if.ipAddress }}/{{ $.Values.global.upf.multus.n3network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.upf.multus.n3network.gatewayIP }}" ]
            },
            { "name": "{{ $.Values.global.upf.multus.n6network.name }}-{{ include "free5gc-upf.fullname" $ }}",
              "interface": "n6",
              "ips": [ "{{ $.Values.global.upf.multus.upf.n6if.ipAddress }}/{{ $.Values.global.upf.multus.n6network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.upf.multus.n6network.gatewayIP }}" ]
            },
            { "name": "{{ $.Values.global.upf.multus.n4network.name }}-{{ include "free5gc-upf.fullname" $ }}",
              "interface": "n4",
              "ips": [ "{{ $.Values.global.upf.multus.upf.n4if.ipAddress }}/{{ $.Values.global.upf.multus.n4network.cidr }}" ],
              "gateway": [ "{{ $.Values.global.upf.multus.n4network.gatewayIP }}" ]
            }
            ]'
        {{- end }}
        checksum/config: {{ include (print $.Template.BasePath "/upf/upf-configmap.yaml") $ | sha256sum }}
      labels:
        {{- include "free5gc-upf.selectorLabels" $ | nindent 8 }}
        project: {{ $.Values.global.projectName }}
        nf: {{ .name }}
    spec:
      serviceAccountName: {{ printf "%s-%s" $.Chart.Name $.Release.Name | trunc 63 | trimSuffix "-" }}
      automountServiceAccountToken: false
      imagePullSecrets:
        {{- toYaml .imagePullSecrets | nindent 8 }}
      securityContext:
        {{- toYaml .podSecurityContext | nindent 8 }}
      containers:
      - name: {{ .name }}
        image: {{ .image.name }}:{{ .image.tag | default $.Chart.AppVersion }}
        imagePullPolicy: {{ .image.pullPolicy }}
        securityContext:
            {{- toYaml .securityContext | nindent 12 }}
        ports:
        - name: n4
          containerPort: 8805
          protocol: UDP
        command: ["{{ .volume.mount }}/wrapper.sh"]
        {{- if .readinessProbe.enabled }}
        readinessProbe:
          {{- if .readinessProbe.httpGet }}
          httpGet:
            {{- toYaml .readinessProbe.httpGet | nindent 12 }}
          {{- end }}
          {{- if .readinessProbe.exec }}
          exec:
            {{- toYaml .readinessProbe.exec | nindent 12 }}
          {{- end }}
          initialDelaySeconds: {{ .readinessProbe.initialDelaySeconds }}
          periodSeconds: {{ .readinessProbe.periodSeconds }}
          timeoutSeconds: {{ .readinessProbe.timeoutSeconds | default 1 }}
          successThreshold: {{ .readinessProbe.successThreshold | default 1 }}
          failureThreshold: {{ .readinessProbe.failureThreshold | default 3 }}
        {{- end }}
        {{- if .livenessProbe.enabled }}
        livenessProbe:
          {{- if .livenessProbe.httpGet }}
          httpGet:
            {{- toYaml .livenessProbe.httpGet | nindent 12 }}
          {{- end }}
          {{- if .livenessProbe.exec }}
          exec:
            {{- toYaml .livenessProbe.exec | nindent 12 }}
          {{- end }}
          initialDelaySeconds: {{ .livenessProbe.initialDelaySeconds }}
          periodSeconds: {{ .livenessProbe.periodSeconds }}
          timeoutSeconds: {{ .livenessProbe.timeoutSeconds | default 10 }}
          successThreshold: {{ .livenessProbe.successThreshold | default 1 }}
          failureThreshold: {{ .livenessProbe.failureThreshold | default 3 }}
        {{- end }}
        volumeMounts:
        - mountPath: {{ .volume.mount }}
          name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-volume
        - mountPath: {{ .volume.tlsmount }}
          name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-empty-volume
        resources:
            {{- toYaml .resources | nindent 12 }}
      dnsPolicy: ClusterFirst
      restartPolicy: Always
      nodeSelector:
        {{- toYaml .nodeSelector | nindent 8 }}
      affinity:
        {{- toYaml .affinity | nindent 8 }}
      tolerations:
        {{- toYaml .tolerations | nindent 8 }}

      volumes:
      - name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-volume
        projected:
          sources:
          - configMap:
              name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-configmap
              items:
              - key: upfcfg.yaml
                path: upfcfg.yaml
              - key: wrapper.sh
                path: wrapper.sh
                mode: 0777
      - name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-empty-volume
        emptyDir: {}
{{- end }}
{{- end }}
---
#
# Software Name : towards5gs-helm
# SPDX-FileCopyrightText: Copyright (c) 2021 Orange
# SPDX-License-Identifier: Apache-2.0
#
# This software is distributed under the Apache License 2.0,
# the text of which is available at https://github.com/Orange-OpenSource/towards5gs-helm/blob/main/LICENSE
# or see the "LICENSE" file for more details.
#
# Author: Abderaouf KHICHANE, Ilhem FAJJARI, Ayoub BOUSSELMI
# Software description: An open-source project providing Helm charts to deploy 5G components (Core + RAN) on top of Kubernetes
#
{{- if eq .Values.global.userPlaneArchitecture "single" }}
{{- with .Values.upf }}
apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ include "free5gc-upf.fullname" $ }}-{{ .name }}-configmap
  labels:
    app: {{ $.Values.global.projectName }}
data:
  upfcfg.yaml: |
    version: 1.0.3
    description: UPF initial local configuration

    # The listen IP and nodeID of the N4 interface on this UPF (Can't set to 0.0.0.0)
    pfcp:
{{- if $.Values.global.upf.multus.enabled }}
      addr: {{ $.Values.global.upf.multus.upf.n4if.ipAddress }} # IP addr for listening
      nodeID: {{ $.Values.global.upf.multus.upf.n4if.ipAddress }} # External IP or FQDN can be reached
{{- else }}
      addr: POD_IP_ADDR # IP addr for listening - replaced at runtime
      nodeID: POD_IP_ADDR # External IP or FQDN can be reached - replaced at runtime
{{- end }}
      retransTimeout: 1s # retransmission timeout
      maxRetrans: 3 # the max number of retransmission

    gtpu:
      forwarder: gtp5g
      # The IP list of the N3/N9 interfaces on this UPF
      # If there are multiple connection, set addr to 0.0.0.0 or list all the addresses
      ifList:
{{- if $.Values.global.upf.multus.enabled }}
        - addr: {{ $.Values.global.upf.multus.upf.n3if.ipAddress }}
          type: N3
{{- else }}
        - addr: POD_IP_ADDR
          type: N3
{{- end }}
          # name: upf.5gc.nctu.me
          # ifname: gtpif

    {{- toYaml .configuration | nindent 4 }}

  wrapper.sh: |
    #!/bin/sh
    set -e

{{- if $.Values.global.upf.multus.enabled }}
    # Multus mode: Static IPs and dedicated interfaces are configured
    echo "[wrapper] Multus mode enabled - using dedicated interfaces"

    # Setup networking rules
    iptables -A FORWARD -j ACCEPT
    iptables -t nat -A POSTROUTING -s {{ $.Values.global.uesubnet }} -o n6 -j MASQUERADE
    echo "1200 n6if" >> /etc/iproute2/rt_tables
    ip rule add from {{ $.Values.global.uesubnet }} table n6if
    ip route add default via {{ $.Values.global.upf.multus.n6network.gatewayIP }} dev n6 table n6if

    {{- if $.Values.upf.configmap.wrapperAdditionalCommands }}
    {{- $.Values.upf.configmap.wrapperAdditionalCommands | nindent 4 }}
    {{- end }}

    exec /free5gc/upf -c {{ .volume.mount }}/upfcfg.yaml
{{- else }}
    # Dynamic Pod IP mode: Single interface (eth0)
    # Get Pod IP dynamically
    POD_IP=$(hostname -i | awk '{print $1}')
    echo "[wrapper] UPF Pod IP detected: $POD_IP"

    # Copy config to writable location
    cp {{ .volume.mount }}/upfcfg.yaml /tmp/upfcfg.yaml

    # Replace POD_IP_ADDR placeholder with actual Pod IP
    sed -i "s/POD_IP_ADDR/$POD_IP/g" /tmp/upfcfg.yaml

    echo "[wrapper] UPF PFCP config:"
    cat /tmp/upfcfg.yaml | grep -A3 "pfcp:"

    # Wait for upfgtp interface to be created by gtp5g module
    echo "[wrapper] Waiting for upfgtp interface..."
    for i in $(seq 1 30); do
      if ip link show upfgtp > /dev/null 2>&1; then
        echo "[wrapper] upfgtp interface is ready"
        break
      fi
      sleep 1
    done

    {{- if $.Values.upf.configmap.wrapperAdditionalCommands }}
    {{- $.Values.upf.configmap.wrapperAdditionalCommands | nindent 4 }}
    {{- end }}

    echo "[wrapper] Starting UPF with dynamic config"
    exec /free5gc/upf -c /tmp/upfcfg.yaml
{{- end }}

{{- end }}
{{- end }}

